package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

const systemPrompt = `You are a process running on a POSIX system. Your mission comes from argv. You have access to a shell tool to execute commands. Output your final result to stdout by responding with text (not a tool call) when done.

Tools available:
- sh: Execute a shell command. Returns stdout and stderr.

When you have the final answer, respond with just the text content (no tool use). That will be printed to stdout.`

type Message struct {
	Role    string      `json:"role"`
	Content interface{} `json:"content"`
}

type ToolUse struct {
	Type  string          `json:"type"`
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

type TextBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type ToolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
	Content   string `json:"content"`
}

type APIRequest struct {
	Model     string    `json:"model"`
	MaxTokens int       `json:"max_tokens"`
	System    string    `json:"system"`
	Messages  []Message `json:"messages"`
	Tools     []Tool    `json:"tools"`
}

type Tool struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"input_schema"`
}

type APIResponse struct {
	Content  []json.RawMessage `json:"content"`
	StopReason string          `json:"stop_reason"`
	Error    *struct {
		Type    string `json:"type"`
		Message string `json:"message"`
	} `json:"error"`
	Type string `json:"type"`
}

func callAPI(apiKey, model string, messages []Message) (*APIResponse, error) {
	tools := []Tool{
		{
			Name:        "sh",
			Description: "Execute a shell command and return its output",
			InputSchema: json.RawMessage(`{"type":"object","properties":{"command":{"type":"string","description":"Shell command to execute"}},"required":["command"]}`),
		},
	}

	reqBody := APIRequest{
		Model:     model,
		MaxTokens: 4096,
		System:    systemPrompt,
		Messages:  messages,
		Tools:     tools,
	}

	body, err := json.Marshal(reqBody)
	if err != nil {
		return nil, fmt.Errorf("marshal: %w", err)
	}

	req, err := http.NewRequest("POST", "https://api.anthropic.com/v1/messages", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("new request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("x-api-key", apiKey)
	req.Header.Set("anthropic-version", "2023-06-01")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("do request: %w", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("read body: %w", err)
	}

	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("API error %d: %s", resp.StatusCode, string(respBody))
	}

	var apiResp APIResponse
	if err := json.Unmarshal(respBody, &apiResp); err != nil {
		return nil, fmt.Errorf("unmarshal response: %w", err)
	}

	if apiResp.Error != nil {
		return nil, fmt.Errorf("API error: %s: %s", apiResp.Error.Type, apiResp.Error.Message)
	}

	return &apiResp, nil
}

func executeShell(command string) string {
	cmd := exec.Command("/bin/sh", "-c", command)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	result := ""
	if stdout.Len() > 0 {
		result += stdout.String()
	}
	if stderr.Len() > 0 {
		result += "\n[STDERR]\n" + stderr.String()
	}
	if err != nil {
		result += "\n[EXIT CODE] " + err.Error()
	} else {
		result += "\n[EXIT CODE] 0"
	}
	return result
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s <mission>\n", os.Args[0])
		os.Exit(1)
	}

	mission := strings.Join(os.Args[1:], " ")
	apiKey := os.Getenv("ANTHROPIC_API_KEY")
	if apiKey == "" {
		fmt.Fprintf(os.Stderr, "ANTHROPIC_API_KEY not set\n")
		os.Exit(1)
	}

	model := os.Getenv("QUINE_MODEL_ID")
	if model == "" {
		model = "claude-sonnet-4-20250514"
	}

	messages := []Message{
		{Role: "user", Content: mission},
	}

	maxTurns := 30
	for turn := 0; turn < maxTurns; turn++ {
		resp, err := callAPI(apiKey, model, messages)
		if err != nil {
			fmt.Fprintf(os.Stderr, "API call failed: %v\n", err)
			os.Exit(1)
		}

		// Parse content blocks
		var assistantContent []interface{}
		var toolUses []ToolUse
		var textParts []string

		for _, raw := range resp.Content {
			var block map[string]interface{}
			json.Unmarshal(raw, &block)

			blockType, _ := block["type"].(string)
			if blockType == "text" {
				var tb TextBlock
				json.Unmarshal(raw, &tb)
				textParts = append(textParts, tb.Text)
				assistantContent = append(assistantContent, tb)
			} else if blockType == "tool_use" {
				var tu ToolUse
				json.Unmarshal(raw, &tu)
				toolUses = append(toolUses, tu)
				assistantContent = append(assistantContent, tu)
			}
		}

		// Add assistant message with raw content
		messages = append(messages, Message{Role: "assistant", Content: resp.Content})

		// If no tool use, we're done - output text
		if resp.StopReason == "end_turn" || len(toolUses) == 0 {
			fmt.Print(strings.Join(textParts, ""))
			return
		}

		// Execute tool calls and build results
		var toolResults []ToolResultBlock
		for _, tu := range toolUses {
			if tu.Name == "sh" {
				var input struct {
					Command string `json:"command"`
				}
				json.Unmarshal(tu.Input, &input)
				result := executeShell(input.Command)
				toolResults = append(toolResults, ToolResultBlock{
					Type:      "tool_result",
					ToolUseID: tu.ID,
					Content:   result,
				})
				fmt.Fprintf(os.Stderr, "[turn %d] sh: %s\n", turn, input.Command)
			}
		}

		// Add tool results as user message
		messages = append(messages, Message{Role: "user", Content: toolResults})
	}

	fmt.Fprintf(os.Stderr, "Max turns reached\n")
	os.Exit(1)
}
GOEOF
